{{RULE:project-directory}}

{{RULE:git-rules}}

(function prepare(mode) {
  const fs = require('node:fs');
  const path = require('node:path');
  const { execFileSync } = require('node:child_process');
  const assert = require('node:assert/strict');
  const cwd = process.cwd();
  assert.ok(fs.existsSync('.git'), 'Only run in the disposable fixture repository');
  assert.ok(!fs.existsSync('.git/split-state.json'), 'Fixture preparation runs once');
  const git = (...args) => execFileSync('git', args, { cwd, encoding: 'utf8', windowsHide: true, stdio: ['ignore', 'pipe', 'pipe'] }).trim();
  git('config', 'user.name', 'Split Push Fixture');
  git('config', 'user.email', 'split-push@example.invalid');
  git('config', 'core.autocrlf', 'false');
  git('branch', '-m', 'develop');
  const remote = path.join(cwd, '.git', 'split-remote.git');
  git('init', '--bare', '-q', '-b', 'develop', remote);
  git('remote', 'add', 'origin', remote);
  git('push', '-q', '-u', 'origin', 'HEAD:refs/heads/develop');
  const base = git('rev-parse', 'HEAD');
  let remoteHead = base;
  if (['diverged', 'conflict', 'fast-forward'].includes(mode)) {
    const peer = path.join(cwd, '.git', 'split-peer');
    git('clone', '-q', remote, peer);
    const other = (...args) => git('-C', peer, ...args);
    other('config', 'user.name', 'Remote Fixture');
    other('config', 'user.email', 'remote@example.invalid');
    fs.writeFileSync(path.join(peer, mode === 'conflict' ? 'app.cjs' : 'remote.txt'), mode === 'conflict' ? 'exports.sum = (a, b) => a + b + 0;\n' : 'remote change\n');
    other('add', '--all');
    other('commit', '-qm', 'docs(remote): record remote change');
    other('push', '-q', 'origin', 'HEAD:refs/heads/develop');
    remoteHead = other('rev-parse', 'HEAD');
  }
  if (mode !== 'fast-forward') {
    fs.writeFileSync('app.cjs', 'exports.sum = (a, b) => a + b;\nexports.multiply = (a, b) => a * b;\n');
    git('add', 'app.cjs');
    fs.writeFileSync('guide.md', 'Sum and multiply usage.\n');
    fs.writeFileSync('notes.md', 'Examples for the usage guide.\n');
  }
  if (mode === 'excluded') {
    fs.writeFileSync('excluded.txt', 'edited private working note\n');
    git('add', 'excluded.txt');
    fs.writeFileSync('scratch.txt', 'untracked private note\n');
  }
  if (mode === 'ambiguous') {
    const second = path.join(cwd, '.git', 'split-other.git');
    git('init', '--bare', '-q', '-b', 'develop', second);
    git('config', '--add', 'remote.origin.pushurl', remote);
    git('config', '--add', 'remote.origin.pushurl', second);
  }
  if (mode === 'hook') {
    fs.writeFileSync('.git/hooks/pre-commit', '#!/bin/sh\nprintf attempted > .git/hook-ran\nexit 1\n', { mode: 0o755 });
    git('config', 'core.hooksPath', '.git/hooks');
  }
  fs.writeFileSync('.git/split-state.json', JSON.stringify({ mode, base, remoteHead, remote }));
})("existing");

