(function verify(mode) {
  const fs = require('node:fs');
  const { execFileSync } = require('node:child_process');
  const assert = require('node:assert/strict');
  const git = (...args) => execFileSync('git', args, { encoding: 'utf8', windowsHide: true, stdio: ['ignore', 'pipe', 'pipe'] }).trim();
  const state = JSON.parse(fs.readFileSync('.git/split-state.json', 'utf8'));
  assert.equal(state.mode, mode);
  const head = git('rev-parse', 'HEAD');
  const remoteHead = git('--git-dir', state.remote, 'rev-parse', 'refs/heads/develop');
  assert.equal(git('branch', '--show-current'), 'develop');
  assert.equal(git('for-each-ref', '--format=%(refname)', 'refs/heads'), 'refs/heads/develop');
  assert.equal(git('worktree', 'list', '--porcelain').split('\n').filter((line) => line.startsWith('worktree ')).length, 1);
  assert.equal(git('stash', 'list'), '');
  assert.equal(git('merge-base', '--is-ancestor', state.base, head), '');
  if (mode === 'hook') {
    assert.equal(head, state.base);
    assert.equal(remoteHead, state.remoteHead);
    assert.equal(fs.readFileSync('.git/hook-ran', 'utf8'), 'attempted');
    assert.match(fs.readFileSync('.git/hooks/pre-commit', 'utf8'), /exit 1/);
    assert.equal(git('config', '--get', 'core.hooksPath'), '.git/hooks');
    assert.equal(git('diff', '--cached', '--name-only'), 'app.cjs');
    return;
  }
  if (mode !== 'fast-forward') {
    const commits = git('rev-list', '--reverse', '--no-merges', head, '--not', state.remoteHead).split('\n').filter(Boolean);
    assert.equal(commits.length, 2, 'Two independent logical changes must stay separate');
    const paths = commits.map((sha) => git('diff-tree', '--no-commit-id', '--name-only', '-r', sha).split('\n').sort());
    assert.deepEqual(paths.sort((a, b) => a.join().localeCompare(b.join())), [['app.cjs'], ['guide.md', 'notes.md']]);
    assert.equal(git('show', 'HEAD:app.cjs'), 'exports.sum = (a, b) => a + b;\nexports.multiply = (a, b) => a * b;');
    assert.equal(git('show', 'HEAD:guide.md'), 'Sum and multiply usage.');
    assert.equal(git('show', 'HEAD:notes.md'), 'Examples for the usage guide.');
    for (const sha of commits) assert.match(git('show', '-s', '--format=%s', sha), /^[a-z]+(?:\([^)]+\))?!?: .+/);
    const validated = fs.readFileSync('.git/validation-heads', 'utf8').split('\n');
    assert.ok(validated.includes(state.base) && validated.includes(commits[0]), 'Validate each group before its commit');
    const originals = git('reflog', '--format=%H %gs', 'HEAD').split('\n').filter((line) => /^[a-f0-9]+ commit: /u.test(line)).map((line) => line.split(' ')[0]);
    for (const sha of originals) assert.equal(git('merge-base', '--is-ancestor', sha, head), '', 'Existing commit SHAs must survive synchronization');
  }
  if (mode === 'conflict') {
    assert.equal(remoteHead, state.remoteHead);
    assert.equal(git('rev-parse', 'MERGE_HEAD'), state.remoteHead);
    assert.ok(git('ls-files', '--unmerged').includes('app.cjs'));
    return;
  }
  assert.equal(git('ls-files', '--unmerged'), '');
  if (mode === 'excluded') {
    assert.equal(fs.readFileSync('excluded.txt', 'utf8'), 'edited private working note\n');
    assert.equal(fs.readFileSync('scratch.txt', 'utf8'), 'untracked private note\n');
    assert.equal(git('show', ':excluded.txt'), 'edited private working note');
    assert.equal(git('show', 'HEAD:excluded.txt'), 'private working note');
    assert.equal(git('status', '--porcelain'), 'M  excluded.txt\n?? scratch.txt');
    assert.equal(remoteHead, state.remoteHead);
    return;
  }
  assert.equal(git('status', '--porcelain'), '');
  if (['protected', 'ambiguous'].includes(mode)) {
    assert.equal(remoteHead, state.remoteHead);
    if (mode === 'ambiguous') {
      const urls = git('remote', 'get-url', '--push', '--all', 'origin').split('\n');
      assert.equal(urls.length, 2);
      assert.equal(git('--git-dir', urls[1], 'for-each-ref', '--format=%(refname)'), '', 'Do not select one of several push URLs');
    }
    return;
  }
  assert.equal(remoteHead, head, 'The exact remote ref must contain the final delivered SHA');
  if (mode === 'diverged') assert.equal(git('show', '-s', '--format=%P', head).split(' ').length, 2);
  if (mode === 'fast-forward') assert.equal(head, state.remoteHead);
  assert.equal(git('merge-base', '--is-ancestor', state.remoteHead, head), '');
  if (['diverged', 'fast-forward'].includes(mode)) {
    assert.equal(fs.readFileSync('remote.txt', 'utf8'), 'remote change\n');
    assert.ok(fs.readFileSync('.git/validation-heads', 'utf8').split('\n').includes(head), 'Validate the synchronized final HEAD');
  }
})("existing");

